/* DODO WORLD About Page — '도도는 아직 여행 중입니다.'
 * 설치: about.html 의 </body> 바로 윗줄에 다음 한 줄을 추가하세요.
 * <script defer src="./about-extra.js"></script>
 * 기존 페이지의 다른 요소는 수정하지 않습니다.
 */
(function(){
  "use strict";
  function mount(){
    if(document.getElementById('dodo-about-addition')) return;
    var styles = document.createElement('style');
    styles.id='dodo-about-addition-style';
    styles.textContent = `
      #dodo-about-addition{--dodo-a-green:#193b30;--dodo-a-gold:#caa66a;--dodo-a-paper:#eae7dc;font-family:inherit;color:#f7f7ed;font-size:16px;line-height:1.6}
      #dodo-about-addition *{box-sizing:border-box}
      #dodo-about-addition .dodo-letter{background:var(--dodo-a-green);padding:92px 0 95px;position:relative;overflow:hidden}
      #dodo-about-addition .dodo-letter:before{content:'';position:absolute;right:-270px;top:-200px;width:650px;height:650px;border:1px solid rgba(255,255,255,.07);border-radius:50%;pointer-events:none}
      #dodo-about-addition .dodo-letter:after{content:'';position:absolute;right:-145px;top:-120px;width:400px;height:400px;border:1px solid rgba(255,255,255,.07);border-radius:50%;pointer-events:none}
      #dodo-about-addition .dodo-limit{width:100%;max-width:1190px;margin:0 auto;padding-left:30px;padding-right:30px}
      #dodo-about-addition .dodo-letter-grid{display:grid;grid-template-columns:43% 57%;min-height:710px;position:relative;z-index:1}
      #dodo-about-addition .dodo-letter-photo{position:relative;min-height:680px;overflow:hidden;background:#52685f}
      #dodo-about-addition .dodo-letter-photo img{display:block;position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
      #dodo-about-addition .dodo-letter-photo:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(18,46,36,.43),transparent 45%)}
      #dodo-about-addition .dodo-photo-note{position:absolute;z-index:1;bottom:28px;left:28px;right:20px;font:700 12px/1.5 Georgia,serif;letter-spacing:1.6px;color:#f7efd9}
      #dodo-about-addition .dodo-letter-copy{padding:49px 2% 40px clamp(45px,6vw,92px);display:flex;flex-direction:column;justify-content:center}
      #dodo-about-addition .dodo-eyebrow{color:#e4bd7a;font:700 11px/1.5 Georgia,serif;letter-spacing:2.1px}
      #dodo-about-addition .dodo-letter-title{font-family:'Noto Serif KR','Batang','AppleMyungjo',serif;font-size:clamp(38px,4vw,56px);letter-spacing:-.045em;font-weight:500;line-height:1.35;color:#fbf9ef;margin:21px 0 19px;padding:0}
      #dodo-about-addition .dodo-letter-quote{font-family:'Noto Serif KR','Batang',serif;font-size:16px;color:#dec79d;line-height:1.65;margin:0 0 34px}
      #dodo-about-addition .dodo-letter-body{font-size:14px;color:#dfebe1;line-height:2.05;font-weight:400}
      #dodo-about-addition .dodo-letter-body p{margin:0 0 18px}
      #dodo-about-addition .dodo-letter-body strong{color:#fff9e9;font-weight:700}
      #dodo-about-addition .dodo-letter-signoff{border-top:1px solid rgba(255,255,255,.22);margin-top:20px;padding-top:25px;display:flex;align-items:center;justify-content:space-between;gap:20px}
      #dodo-about-addition .dodo-letter-signature{font-weight:700;font-size:13px;color:#faf4e5}
      #dodo-about-addition .dodo-letter-signature span{font:400 10px/1.7 Georgia,serif;letter-spacing:.11em;color:#bcac84;display:block;margin-top:9px}
      #dodo-about-addition .dodo-seal{border:1px solid rgba(204,211,185,.4);color:#d0c4aa;font:700 15px Georgia,serif;width:48px;height:48px;border-radius:50%;display:grid;place-items:center;flex:none}
      #dodo-about-addition .dodo-endcap{background:var(--dodo-a-paper);padding:34px 0;color:#1d352b}
      #dodo-about-addition .dodo-endrow{display:flex;align-items:center;justify-content:space-between;gap:26px}
      #dodo-about-addition .dodo-endrow small{display:block;font:700 10px/1.5 Georgia,serif;letter-spacing:2px;color:#a27f48;margin-bottom:8px}
      #dodo-about-addition .dodo-endrow p{font-size:17px;font-weight:700;margin:0;color:#1d352b}
      #dodo-about-addition .dodo-links{display:flex;gap:10px}
      #dodo-about-addition .dodo-links a{display:inline-flex;align-items:center;justify-content:center;min-width:148px;padding:13px 22px;text-decoration:none;border:1px solid #285043;border-radius:99px;font-size:12px;font-weight:700;white-space:nowrap}
      #dodo-about-addition .dodo-links a:first-child{background:#214b3c;color:#fff}
      #dodo-about-addition .dodo-links a:last-child{color:#214b3c;background:transparent}
      #dodo-about-addition .dodo-links a:hover{filter:brightness(1.08)}
      @media(max-width:900px){
        #dodo-about-addition .dodo-letter-grid{grid-template-columns:42% 58%}
        #dodo-about-addition .dodo-letter-copy{padding-left:33px}
        #dodo-about-addition .dodo-letter-title{font-size:37px}
        #dodo-about-addition .dodo-letter-body{font-size:13px}
        #dodo-about-addition .dodo-letter-photo{min-height:760px}
      }
      @media(max-width:640px){
        #dodo-about-addition .dodo-limit{padding-left:20px;padding-right:20px}
        #dodo-about-addition .dodo-letter{padding:0 0 67px}
        #dodo-about-addition .dodo-letter-grid{display:flex;flex-direction:column}
        #dodo-about-addition .dodo-letter-photo{min-height:415px}
        #dodo-about-addition .dodo-letter-copy{padding:50px 18px 0}
        #dodo-about-addition .dodo-letter-title{font-size:39px}
        #dodo-about-addition .dodo-letter-body{font-size:13px}
        #dodo-about-addition .dodo-endrow{flex-direction:column;align-items:stretch}
        #dodo-about-addition .dodo-links{width:100%}
        #dodo-about-addition .dodo-links a{flex:1;min-width:0;padding:12px 8px;font-size:11px}
      }
    `;
    document.head.appendChild(styles);

    var host = document.createElement('div');
    host.id = 'dodo-about-addition';
    host.innerHTML = `
      <section class="dodo-letter" aria-label="대표의 이야기">
        <div class="dodo-limit dodo-letter-grid">
          <div class="dodo-letter-photo">
            <img src="data:image/webp;base64," alt="황금빛 햇살이 드는 작은 간이역과 여행 가방" decoding="async" loading="lazy" />
            <span class="dodo-photo-note">THE JOURNEY CONTINUES · DODO WORLD</span>
          </div>
          <div class="dodo-letter-copy">
            <span class="dodo-eyebrow">A LETTER FROM DODO</span>
            <h2 class="dodo-letter-title">도도는 아직<br>여행 중입니다.</h2>
            <p class="dodo-letter-quote">좋은 공간은 오래 남습니다.</p>
            <div class="dodo-letter-body">
              <p>처음 도도를 구상하면서 가장 중요하게 생각했던 것은 단순히 좋은 시설이나 화려한 공간을 만드는 일이 아니었습니다. <strong>누구나 부담 없이 찾아와 편안하게 머물 수 있는 공간</strong>을 만들고 싶었습니다.</p>
              <p>책 한 권을 읽는 시간, 친구와 함께 웃는 시간, 따뜻한 음식을 나누는 시간. 일상의 작은 즐거움이 도도 안에서 자연스럽게 이어지기를 바랍니다.</p>
              <p>좋은 브랜드는 매장의 숫자보다 시간이 흘러도 지켜지는 원칙과 신뢰로 완성된다고 믿습니다. 고객에게는 합리적인 경험을, 가맹점에는 지속 가능한 운영을, 함께하는 모든 사람에게는 정직한 가치를 전하겠습니다.</p>
              <p><strong>도도의 여행은 이제 막 시작되었습니다.</strong><br>다음 여행지에서도 처음과 같은 마음으로 만나겠습니다.</p>
            </div>
            <div class="dodo-letter-signoff">
              <div class="dodo-letter-signature">만화카페 도도 대표<span>DODO WORLD · WITH SINCERITY</span></div>
              <span class="dodo-seal" aria-hidden="true">D</span>
            </div>
          </div>
        </div>
      </section>
      <section class="dodo-endcap" aria-label="도도의 다음 여행지">
        <div class="dodo-limit dodo-endrow">
          <div><small>OUR NEXT DESTINATION</small><p>도도의 다음 여행도 함께해 주세요.</p></div>
          <div class="dodo-links">
            <a href="./stores.html">매장 둘러보기 →</a>
            <a href="./franchise.html">가맹문의 →</a>
          </div>
        </div>
      </section>`;
    var footer = document.querySelector('footer');
    if(footer) footer.parentNode.insertBefore(host,footer);
    else (document.querySelector('main') || document.body).appendChild(host);
  }
  if(document.readyState === 'loading')document.addEventListener('DOMContentLoaded',mount,{once:true});
  else mount();
})();
